pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address public constant ORIGINAL_OWNER = address(0);

    function setUp() public { 
        c = new C(); 
    }

    function testFuzz_property(address caller) public {
        // Restrict caller to be the owner for valid calls
        vm.assume(caller == c.owner());

        // Record owner before call
        address ownerBefore = c.owner();

        // Call owned() as the owner
        vm.prank(caller);
        c.owned();

        // After owned() completes, owner should remain unchanged
        assertTrue(c.owner() == ownerBefore);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0)); // avoid zero address
        // Initially, owner is address(0) since not set; set it to caller
        // We need to call transferOwnership as the current owner to set initial owner
        // But we can't easily do that without knowing current owner; instead, assume we start with owner = address(0) and call transferOwnership from that address
        vm.prank(address(0));
        c.transferOwnership(caller);
        // Now owner = caller
        // Now call owned() from any caller (including non-owner)
        vm.prank(caller);
        c.owned();
        // After owned(), owner should remain caller (since onlyOwner does not change it)
        assertTrue(c.owner() == caller);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // Set owner to this contract via transferOwnership
        vm.prank(c.owner()); // pre-existing owner is address(0) initially
        c.transferOwnership(address(this));
        // Now this contract is owner
        address ownerBefore = c.owner();
        vm.prank(address(this));
        c.owned();
        address ownerAfter = c.owner();
        assertTrue(ownerAfter == ownerBefore, "Owner should remain unchanged after owned()");
    }
}
